# Tambah 5 proxy agents + VPSO + archivist sekaligus
cat >> /etc/nginx/sites-available/workstation-upshalter << 'EOF'

    # Main Hermes Agent (Host) - Port 9119
    location /hermes/main {
        proxy_pass http://127.0.0.1:9119;
        proxy_set_header Host $host;
